import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.apache.commons.lang3.exception.ExceptionUtils;

private static final Logger logger = LoggerFactory.getLogger(MyService.class);

public ResponseEntity<Map<String,Object>> handleRequest(Request req) {
    try {
        // call into business logic
        return ResponseEntity.ok(service.doWork(req));
    } catch (Exception e) {
        // Log with full stacktrace and root cause message
        logger.error("Unhandled error in serviceId={} endpoint={}: {}", "<SERVICE_ID>", "<ENDPOINT>", e.toString(), e);
        String rootCause = ExceptionUtils.getRootCauseMessage(e);
        Map<String,Object> body = Map.of(
            "error", "internal_error",
            "message", rootCause != null ? rootCause : e.getMessage()
        );
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(body);
    }
}

