// Controller-level logging and defensive check
@GetMapping("/example")
public ResponseEntity<String> exampleEndpoint(@RequestParam(required = false) String id) {
    if (id == null || id.isBlank()) {
        log.warn("exampleEndpoint called with missing id");
        return ResponseEntity.badRequest().body("missing id");
    }
    try {
        // business logic
        return ResponseEntity.ok(service.doWork(id));
    } catch (SpecificDependencyException ex) {
        log.error("Dependency failure calling doWork for id={}", id, ex);
        throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "downstream error", ex);
    } catch (Exception ex) {
        log.error("Unhandled error in exampleEndpoint for id={}", id, ex);
        throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR, "internal error", ex);
    }
}

// Global handler to ensure stack traces are logged and minimal info returned to clients
@ControllerAdvice
public class GlobalExceptionHandler {
    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Map<String,Object>> handleAll(Exception ex, WebRequest request) {
        log.error("Unhandled exception at {}: {}", request.getDescription(false), ex);
        Map<String,Object> body = Map.of(
            "error", "internal_error",
            "message", "An internal error occurred",
            "timestamp", Instant.now().toString()
        );
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(body);
    }
}

