/* Spring Boot centralized exception handler that logs full stack trace and returns an error id */
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import java.io.PrintWriter;
import java.io.StringWriter;
import java.util.UUID;

@ControllerAdvice
public class GlobalExceptionHandler {
    private static final Logger logger = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Object> handleAll(Exception ex) {
        // create a correlation id for this failure
        String errorId = UUID.randomUUID().toString();
        MDC.put("errorId", errorId);

        // capture full stack trace
        StringWriter sw = new StringWriter();
        ex.printStackTrace(new PrintWriter(sw));
        String fullTrace = sw.toString();

        // log structured message including correlation id
        logger.error("Unhandled exception (errorId={}) - message: {}\nstack: {}",
                     errorId, ex.getMessage(), fullTrace);

        MDC.remove("errorId");

        // return minimal info to client with error id to correlate logs
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(Map.of("errorId", errorId, "message", "internal server error"));
    }
}

/* Spring Boot example: centralized exception handler that logs full stack trace and returns structured error with traceId */

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import javax.servlet.http.HttpServletRequest;
import java.util.UUID;

@ControllerAdvice
public class GlobalExceptionHandler {
    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleAll(Exception ex, HttpServletRequest req) {
        String traceId = req.getHeader("X-Trace-Id");
        if (traceId == null) traceId = UUID.randomUUID().toString();

        // Log full stack trace and contextual request info
        log.error("Unhandled exception: traceId={} service={} path={} method={} message={}",
                traceId,
                req.getServerName(),
                req.getRequestURI(),
                req.getMethod(),
                ex.getMessage(),
                ex);

        ErrorResponse body = new ErrorResponse("internal_error", "An internal error occurred", traceId);
        return new ResponseEntity<>(body, HttpStatus.INTERNAL_SERVER_ERROR);
    }

    public static class ErrorResponse {
        public String code;
        public String message;
        public String traceId;

        public ErrorResponse(String code, String message, String traceId) {
            this.code = code;
            this.message = message;
            this.traceId = traceId;
        }
    }
}

