/* Example: validate incoming failure report and log helpful data (Java, SLF4J) */
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class FailureReportHandler {
    private static final Logger log = LoggerFactory.getLogger(FailureReportHandler.class);

    public void handleReport(String serviceId, String endpoint, String errorMessage, String stackTrace) {
        if (isPlaceholder(serviceId) || isPlaceholder(endpoint) || isPlaceholder(errorMessage) || isPlaceholder(stackTrace)) {
            log.warn("Received failure report with unresolved placeholders. serviceId={}, endpoint={}", serviceId, endpoint);
            // reject or return a helpful error to the sender
            return;
        }

        // Normal processing: persist or forward the report, attach correlation id
        log.error("Failure report received for service={} endpoint={} error={}\nstackTrace={}",
                  serviceId, endpoint, errorMessage, stackTrace);
    }

    private boolean isPlaceholder(String s) {
        return s == null || s.isEmpty() || s.contains("{{$json.") || s.matches("\\{\\{.+\\}\\}");
    }
}

