import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.regex.Pattern;

public class PayloadValidator {
    private static final Pattern UNRESOLVED_PLACEHOLDER = Pattern.compile("\\{\\{\\$json\\.[^}]+\\}\\}");
    private static final ObjectMapper MAPPER = new ObjectMapper();

    public static JsonNode validateAndParse(String payload) throws Exception {
        if (payload == null || payload.isBlank()) {
            throw new IllegalArgumentException("Empty payload");
        }

        if (UNRESOLVED_PLACEHOLDER.matcher(payload).find()) {
            // Log context and fail-fast so upstream systems see the instrumentation problem
            // Replace with application logger as appropriate
            System.err.println("ERROR: Unresolved template placeholders detected in payload: " + payload);
            throw new IllegalArgumentException("Unresolved template placeholders in payload");
        }

        // Safe to parse
        return MAPPER.readTree(payload);
    }
}

// Usage: call validateAndParse before relying on extracted fields; this surfaces templating failures early.

/* Example: capture root cause, log with context, return safe error to client */
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.apache.commons.lang3.exception.ExceptionUtils;

private static final Logger log = LogManager.getLogger(MyService.class);

public ResponseEntity<Object> handleRequest(Request req) {
    try {
        // service logic
    } catch (Exception e) {
        String root = ExceptionUtils.getRootCauseMessage(e);
        String stack = ExceptionUtils.getStackTrace(e);
        log.error("ServiceId={}, endpoint={}, errorType={}, rootCause={}",
                  "<SERVICE_ID>", req.getPath(), e.getClass().getName(), root);
        // optionally send stack to secure error-collector, not to client
        secureErrorCollector.capture(e, Map.of("service", "<SERVICE_ID>", "endpoint", req.getPath()));
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                             .body(Map.of("error", "internal_error", "id", UUID.randomUUID().toString()));
    }
}

/* Centralized error handling (Spring Boot example) */
@ControllerAdvice
public class GlobalExceptionHandler {
    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Map<String,Object>> handleAll(Exception ex, WebRequest req) {
        log.error("Unhandled exception processing request", ex);
        Map<String,Object> body = new HashMap<>();
        body.put("error", "internal_error");
        body.put("message", ex.getMessage());
        body.put("timestamp", Instant.now().toString());
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(body);
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Map<String,Object>> handleValidation(MethodArgumentNotValidException ex) {
        Map<String,Object> body = new HashMap<>();
        body.put("error", "invalid_request");
        String details = ex.getBindingResult().getFieldErrors().stream()
            .map(fe -> fe.getField() + ": " + fe.getDefaultMessage())
            .collect(Collectors.joining(", "));
        body.put("message", details);
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(body);
    }
}

