/* Example: Spring Boot ControllerAdvice to log and emit structured error details */
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@ControllerAdvice
public class GlobalExceptionHandler {
    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Object> handleAll(Exception ex, HttpServletRequest req) {
        String requestId = req.getHeader("X-Request-Id");
        log.error("Unhandled exception. requestId={} path={} method={} payload={}",
                  requestId, req.getRequestURI(), req.getMethod(), extractPayload(req), ex);
        Map<String,Object> body = Map.of(
            "error", ex.getClass().getName(),
            "message", ex.getMessage(),
            "requestId", requestId
        );
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(body);
    }

    private String extractPayload(HttpServletRequest req) {
        // implement safe payload extraction (limiting size / redacting PII)
        return "<payload-snipped>";
    }
}

/* Example: controller-level validation and robust error handling */
@RestController
@RequestMapping("/api")
public class MyController {
    private static final Logger LOG = LoggerFactory.getLogger(MyController.class);

    @PostMapping("/doSomething")
    public ResponseEntity<?> doSomething(@Valid @RequestBody MyRequest req) {
        try {
            ServiceResult res = myService.process(req);
            return ResponseEntity.ok(res);
        } catch (IllegalArgumentException ex) {
            LOG.warn("Bad request payload: {}", ex.getMessage(), ex);
            return ResponseEntity.badRequest().body(Map.of("error", ex.getMessage()));
        } catch (TimeoutException ex) {
            LOG.error("Downstream timeout", ex);
            return ResponseEntity.status(HttpStatus.GATEWAY_TIMEOUT).body(Map.of("error", "downstream timeout"));
        } catch (Exception ex) {
            LOG.error("Unexpected error while processing request: {}", ex.getMessage(), ex);
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(Map.of("error", "internal error"));
        }
    }
}

