const axios = require('axios');

async function chargePayment(data) {
    const maxRetries = 3;
    for (let attempt = 0; attempt < maxRetries; attempt++) {
        try {
            const response = await axios.post('/api/v1/charge', data);
            return response.data;
        } catch (error) {
            if (attempt === maxRetries - 1) {
                throw new Error('Charge payment failed after multiple attempts');
            }
            console.log(`Attempt ${attempt + 1} failed: ${error.message}. Retrying...`);
        }
    }
}

